INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12001, 'Job 6:11', 'Job', 6, 11, '&nbsp;زما دومره طاقت نشته چې زۀ دا برداشت کړم، او چې زما څۀ اُميد نشته نو بيا زۀ ولې ژوندے يم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12002, 'Job 6:12', 'Job', 6, 12, '&nbsp;زما طاقت لکه د کاڼو دے څۀ؟ زما بدن د اوسپنې نه جوړ دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12003, 'Job 6:13', 'Job', 6, 13, '&nbsp;په حقيقت کښې زۀ د خپل ځان سره د مدد کولو وس نۀ لرم، او خلاصون زما نه تلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12004, 'Job 6:14', 'Job', 6, 14, '&nbsp;يو کس له په کار وى چې په خپل کمزورى دوست باندې رحم وکړى، خو تاسو سره د قادر خُدائ يره نۀ وى او په ما اِلزام لګوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12005, 'Job 6:15', 'Job', 6, 15, '&nbsp;زما وروڼو، تاسو ما سره د خوړ په شان دوکه بازى کوئ، چې کله باران نۀ وى نو دا اوچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12006, 'Job 6:16', 'Job', 6, 16, '&nbsp;چې د ويلې شوې واورې د اوبو نه ډک وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12007, 'Job 6:17', 'Job', 6, 17, '&nbsp;خو د ګرمۍ په وخت کښې دا اوبۀ اوچې شى، کله چې ګرمى شى، نو دا فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12008, 'Job 6:18', 'Job', 6, 18, '&nbsp;د اوبو لټولو دپاره قافلې خپلې لارې بدلې کړى، خو د څښلو دپاره اوبۀ نۀ وى، نو هغوئ مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12009, 'Job 6:19', 'Job', 6, 19, '&nbsp;د تيما قافلې دا اوبۀ لټوى، او د شيبا مسافر دا اُميد لرى چې اوبۀ به پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12010, 'Job 6:20', 'Job', 6, 20, '&nbsp;د قافلې يقين وى چې هغوئ به اوبۀ پېدا کړى، خو چې کله هلته ورسيږى نو هغوئ مايُوسه شى او اُميد يې ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12011, 'Job 6:21', 'Job', 6, 21, '&nbsp;اوس تاسو هم د دې اوچ خوړ په شان يئ چې بې‌کاره دے، تاسو زما مصيبت وليدلو او ويرېدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12012, 'Job 6:22', 'Job', 6, 22, '&nbsp;ولې ما وئيلى دى څۀ، چې ما له تُحفه راکړئ؟ يا مې د پېسو دپاره تا ته کله مِنت کړے دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12013, 'Job 6:23', 'Job', 6, 23, '&nbsp;يا دا چې د دشمن د لاس نه مې بچ کړئ؟ يا د ظالمانو نه مې خلاص کړئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12014, 'Job 6:24', 'Job', 6, 24, '&nbsp;ما ته وښايئ او زۀ به خاموش شم، ما پوهه کړئ چې زۀ څنګه په غلطه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12015, 'Job 6:25', 'Job', 6, 25, '&nbsp;رښتيا خبرې څومره د درد نه ډکې وى. خو ستاسو د دې بحث نه مطلب څۀ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12016, 'Job 6:26', 'Job', 6, 26, '&nbsp;ستاسو خيال دا دے څۀ چې زما خبرې به صحيح کړئ، او د نا اُميده سړى خبرې بې‌مطلبه ګڼئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12017, 'Job 6:27', 'Job', 6, 27, '&nbsp;تاسو به يتيمان هم خرڅ کړئ، او تاسو به د خپل دوست په سر هم پېسې واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12018, 'Job 6:28', 'Job', 6, 28, '&nbsp;خو اوس ما ته وګورئ، ولې زۀ به تاسو ته دروغ وايم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12019, 'Job 6:29', 'Job', 6, 29, '&nbsp;خپل سوچ بدل کړئ او بې‌اِنصافه مۀ جوړېږئ، داسې وګڼئ چې زۀ په حقه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12020, 'Job 6:30', 'Job', 6, 30, '&nbsp;ستاسو څۀ خيال دے زۀ دروغ وايم څۀ؟ ستاسو په خيال کښې زۀ په رښتيا او دروغو کښې فرق نۀ شم کولے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12021, 'Job 7:1', 'Job', 7, 1, '&nbsp;بنى آدم په دُنيا کښې سخت محنت نۀ کوى څۀ، او د هغوئ ژوند د مزدور په شان نۀ دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12022, 'Job 7:2', 'Job', 7, 2, '&nbsp;لکه چې غلامان د سورى په ارمان وى، او لکه مزدوران د خپلې تنخواه په طمع وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12023, 'Job 7:3', 'Job', 7, 3, '&nbsp;په مياشتو مياشتو زما څۀ مقصد نشته، او د غم شپې ما له راکړے شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12024, 'Job 7:4', 'Job', 7, 4, '&nbsp;کله چې زۀ څملم نو وايم چې، زۀ به کله پاڅم؟ خو شپه اوږده وى، او تر سحر پورې په کټ کښې اوړم راوړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12025, 'Job 7:5', 'Job', 7, 5, '&nbsp;زما بدن د دانو او چينجو نه ډک دے، زما څرمن سخا شى او بيا وشليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12026, 'Job 7:6', 'Job', 7, 6, '&nbsp;زما عُمر د سيلۍ په شان تېز روان دے، او په نااُميدۍ کښې ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12027, 'Job 7:7', 'Job', 7, 7, '&nbsp;ياد ساته چې زما ژوند صرف يوه ساه ده، او زما سترګې به بيا هيڅکله ښۀ ورځ ونۀ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12028, 'Job 7:8', 'Job', 7, 8, '&nbsp;تۀ ما اوس وينې خو بيا به مې ونۀ ګورې، تۀ به ما لټوې، خو زۀ به نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12029, 'Job 7:9', 'Job', 7, 9, '&nbsp;لکه څنګه چې وريځ کمه شى او فنا شى، نو چې څوک لاندې قبر ته لاړ شى نو هغه ترې نه بيا هيڅکله نۀ شى راختلے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12030, 'Job 7:10', 'Job', 7, 10, '&nbsp;هغوئ بيا واپس خپلو کورونو ته نۀ شى راتلے، او هغوئ به هيڅکله نۀ ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12031, 'Job 7:11', 'Job', 7, 11, '&nbsp;نو په دې وجه زۀ به خپله خولۀ نۀ بندوم، زۀ به د خپل زړۀ د درد اظهار کوم، زما زړۀ د غصې نه تاو کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12032, 'Job 7:12', 'Job', 7, 12, '&nbsp;زۀ سمندرى بلا يم څۀ؟ چې ما د نظر لاندې ساتې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12033, 'Job 7:13', 'Job', 7, 13, '&nbsp;زۀ د دې دپاره څملم چې آرام وکړم، د دې دپاره چې د درد نه خلاص شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12034, 'Job 7:14', 'Job', 7, 14, '&nbsp;نو تۀ بيا ما په خوبونو کښې يروې او په تصور کښې مې يروې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12035, 'Job 7:15', 'Job', 7, 15, '&nbsp;نو زما دپاره د ساه بندېدل ښۀ دى، د داسې کړاؤ نه په مرګ خوشحال يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12036, 'Job 7:16', 'Job', 7, 16, '&nbsp;زۀ د خپل ژوند نه نفرت کوم، زۀ به همېشه ژوندے نۀ يم. په دې لنډ تنګ ژوند کښې ما پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12037, 'Job 7:17', 'Job', 7, 17, '&nbsp;بنى آدم څۀ څيز دے، چې تۀ يې دومره خاص ګڼې، چې تۀ هغوئ ته دومره توجو ورکوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12038, 'Job 7:18', 'Job', 7, 18, '&nbsp;هر سحر يې معائنه کوې، او هر وخت هغوئ معلوموې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12039, 'Job 7:19', 'Job', 7, 19, '&nbsp;تۀ به ما له د يوې لحظې موقع رانۀ کړې چې ساه پکښې واخلم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12040, 'Job 7:20', 'Job', 7, 20, '&nbsp;اے د بنيادمو ليدونکيه، کۀ زۀ ګناه کوم، نو په تا باندې څۀ اثر کوى؟ تا زۀ ولې په نښه کړے يم؟ زۀ په تا باندې بوج جوړ شوے يم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12041, 'Job 7:21', 'Job', 7, 21, '&nbsp;تۀ زما غلطيانې ولې نۀ معاف کوې او زما ګناه ولې نۀ لرې کوې؟ زۀ به ډېر زر په لحد کښې پروت يم، تۀ به ما لټوې، خو زۀ به مړ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12042, 'Job 8:1', 'Job', 8, 1, '&nbsp;بيا بِلداد شوحى ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12043, 'Job 8:2', 'Job', 8, 2, '&nbsp;”ترڅو پورې به تۀ دا خبرې کوې، او دا بک بک به جارى ساتې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12044, 'Job 8:3', 'Job', 8, 3, '&nbsp;خُدائ پاک د اِنصاف نه نۀ اوړى. او د قادر خُدائ کارونه همېشه په حقه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12045, 'Job 8:4', 'Job', 8, 4, '&nbsp;کۀ ستاسو بچو د هغۀ خِلاف ګناه کړې وى، نو هغوئ ته به د هغې بدله مِلاو شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12046, 'Job 8:5', 'Job', 8, 5, '&nbsp;کۀ تۀ خُدائ پاک ولټوې او قادر خُدائ ته په دُعا کښې سوال وکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12047, 'Job 8:6', 'Job', 8, 6, '&nbsp;کۀ تۀ صفا او صادق يې، نو هغه به په خپله راپاڅى او هغه به تا له خپل صحيح مقام واپس درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12048, 'Job 8:7', 'Job', 8, 7, '&nbsp;اګر چې ستا شروع معمولى شان وه، خو په مستقبل کښې به مالدار شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12049, 'Job 8:8', 'Job', 8, 8, '&nbsp;معلوماتو دپاره مخکښېنو نسلونو نه تپوس وکړه، او د هغوئ چې کومې تجربې دى په هغې غور وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12050, 'Job 8:9', 'Job', 8, 9, '&nbsp;ځکه چې مونږ پرون پېدا شوى يُو او مونږ ته هيڅ پته نۀ لګى، ځکه چې په زمکه باندې زمونږ وخت د سورى په شان روان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12051, 'Job 8:10', 'Job', 8, 10, '&nbsp;خو پرېږده چې هوښيار مشران درته ښودنه وکړى، او د هغوئ وېنا ته غوږ نيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12052, 'Job 8:11', 'Job', 8, 11, '&nbsp;چرته چې اوبۀ نۀ وى نو هلته لوخه نۀ را شنه کيږى، دا د اوبو نه بغېر نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12053, 'Job 8:12', 'Job', 8, 12, '&nbsp;او دا لا شنه وى او رېبلے شوې نۀ وى، خو د نورو واښو نه زر وچيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12054, 'Job 8:13', 'Job', 8, 13, '&nbsp;نو چې څوک خُدائ پاک هېروى نو د هغوئ هم دغه لار ده، چې څوک د خُدائ نه منکر وى نو د هغوئ اُميد به ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12055, 'Job 8:14', 'Job', 8, 14, '&nbsp;د هغوئ ايمان نازک وى، د هغوئ يقين د جولا د جالې په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12056, 'Job 8:15', 'Job', 8, 15, '&nbsp;چې څوک په دې جاله يقين کوى نو هغوئ ته به دا جاله ټينګه نۀ شى، کۀ څوک ورپورې ځان وتړى، نو دا به يې برداشت نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12057, 'Job 8:16', 'Job', 8, 16, '&nbsp;منکر کسان داسې ښکارى چې په نمر کښې رازرغون وى، او د دې څانګې په باغ کښې خورې ورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12058, 'Job 8:17', 'Job', 8, 17, '&nbsp;د هغوئ جرړې د کاڼو د ډېرى نه تاويږى، او دا کاڼى کلک نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12059, 'Job 8:18', 'Job', 8, 18, '&nbsp;خو کۀ هغوئ د خپل ځائ نه لرې کړے شى، نو بيا به هغوئ اِنکار وکړى او وائى به چې ما تاسو کله هم نۀ يې ليدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12060, 'Job 8:19', 'Job', 8, 19, '&nbsp;ګوره، د هغوئ خوشحالى به د لږ وخت دپاره وى، خو نور بوټى راشنۀ شى او د دې ځائ ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12061, 'Job 8:20', 'Job', 8, 20, '&nbsp;ګوره، خُدائ پاک به يو بې‌داغه کس نۀ رد کوى، او نۀ به د بدعمله خلقو مدد وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12062, 'Job 8:21', 'Job', 8, 21, '&nbsp;هغه به بيا هم تاسو له خوشحالى درکړى، او ستاسو خولې به د خندا نۀ ډکې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12063, 'Job 8:22', 'Job', 8, 22, '&nbsp;چې څوک ستا نه نفرت کوى نو هغوئ به په شرمونو وشرميږى، او د بدکارانو کور به تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12064, 'Job 9:1', 'Job', 9, 1, '&nbsp;نو ايُوب ورته په جواب کښې وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12065, 'Job 9:2', 'Job', 9, 2, '&nbsp;”په حقيقت کښې ما ته پته ده چې دا هم داسې ده، خو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12066, 'Job 9:3', 'Job', 9, 3, '&nbsp;کۀ يو کس د هغۀ سره لانجه کول وغواړى، نو هيڅ څوک به د هغۀ د زرګونو سوالونو نه د يو جواب هم ورنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12067, 'Job 9:4', 'Job', 9, 4, '&nbsp;ځکه چې هغه زورَور او د حِکمت خاوند دے او څوک هم چې د هغۀ مخالفت کوى نو نقصان به اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12068, 'Job 9:5', 'Job', 9, 5, '&nbsp;هغه ناڅاپه غرونه خوځوى، او په غصه کښې يې تباه کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12069, 'Job 9:6', 'Job', 9, 6, '&nbsp;څوک چې په زمکه زلزله راولى، او د دې بنيادونه خوځوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12070, 'Job 9:7', 'Job', 9, 7, '&nbsp;کۀ هغه حُکم وکړى نو نمر به راونۀ خېژى، او ستورى به ونۀ ځليږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12071, 'Job 9:8', 'Job', 9, 8, '&nbsp;چا چې يواځې آسمانونه خوارۀ کړى دى چا چې د سمندر چپې ايسارې کړې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12072, 'Job 9:9', 'Job', 9, 9, '&nbsp;چا چې ټول ستورى جوړ کړى دى، په دې کښې دب اکبر، جبار او ثريا او جنوبى ستورى هم شامل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12073, 'Job 9:10', 'Job', 9, 10, '&nbsp;څوک چې د عقل نه بهر لوئ لوئ کارونه کوى، او بې‌شمېره عجيبه عجيبه کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12074, 'Job 9:11', 'Job', 9, 11, '&nbsp;ګوره، هغه زما نه تېر شو، خو زۀ هغه نۀ وينم، هغه تېريږى، خو زۀ د هغۀ په تلو نۀ پوهېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12075, 'Job 9:12', 'Job', 9, 12, '&nbsp;چې هغه روح وباسى نو څوک يې منع کولے شى؟ څوک دا جرأت کولے شى چې ورته ووائى چې تۀ څۀ کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12076, 'Job 9:13', 'Job', 9, 13, '&nbsp;خُدائ پاک به د خپلې غصې نه نۀ اوړى، هغۀ سمندرى بلاګانې هم د پښې لاندې چخڼى کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12077, 'Job 9:14', 'Job', 9, 14, '&nbsp;نو زۀ څوک يم چې هغۀ له جواب ورکړم، او زۀ څوک يم چې د هغۀ سره بحث وکړم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12078, 'Job 9:15', 'Job', 9, 15, '&nbsp;اګر چې زۀ بې‌ګناه يم او زۀ هغۀ له جواب نۀ شم ورکولے، زۀ خپل قاضى ته صِرف د رحم درخواست کولے شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12079, 'Job 9:16', 'Job', 9, 16, '&nbsp;کۀ ما هغۀ ته آواز وکړو او هغۀ جواب راکړو، نو زما يقين نۀ دے چې هغه به زما فرياد واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12080, 'Job 9:17', 'Job', 9, 17, '&nbsp;ځکه چې هغۀ زۀ په طوفان وهلے يم، او هغه بار بار ما زخمى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12081, 'Job 9:18', 'Job', 9, 18, '&nbsp;هغه به ما ساه اخستو ته پرې نۀ ږدى، خو زما ژوند به د غمونو نه ډک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12082, 'Job 9:19', 'Job', 9, 19, '&nbsp;کۀ دا د زور خبره وى، نو هغه طاقتور دے. کۀ دا د اِنصاف خبره وى، نو هغه عدالت ته څوک راغوښتے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12083, 'Job 9:20', 'Job', 9, 20, '&nbsp;اګر چې زۀ بې‌ګناه يم، خو زما خپله خولۀ به ما مجرم کړى، اګر چې زۀ بې‌داغه يم، خو خپله خولۀ به ما ګناهګار ثابِتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12084, 'Job 9:21', 'Job', 9, 21, '&nbsp;زۀ بې‌داغه يم، زۀ خپل ځان هم نۀ پېژنم، زۀ خپل ژوند ته سپک ګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12085, 'Job 9:22', 'Job', 9, 22, '&nbsp;ګناهګار او بې‌ګناه ټول د خُدائ پاک په نظر کښې يو شان دى نو ځکه زۀ وايم، هغه بې‌داغه او بدکاره دواړه تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12086, 'Job 9:23', 'Job', 9, 23, '&nbsp;کله چې افت ناڅاپه مرګ راولى، نو هغه د بې‌ګناه په غم پورې ټوقې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12087, 'Job 9:24', 'Job', 9, 24, '&nbsp;ټوله دُنيا د بدکاره په لاس کښې ورکړے شوې ده، خُدائ پاک د قاضيانو سترګې پټوى، کۀ هغه دا نۀ کوى نو بيا يې څوک کوى، او دا څوک دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12088, 'Job 9:25', 'Job', 9, 25, '&nbsp;زما ژوند د منډه وهونکى نه تېز دے، دا په منډه روان دے او هيڅ خوشحالى ورته نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12089, 'Job 9:26', 'Job', 9, 26, '&nbsp;زما ژوند د تېزې کشتۍ په شان روان دے، داسې لکه چې باز په ښکار باندې غوټه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12090, 'Job 9:27', 'Job', 9, 27, '&nbsp;کۀ اراده وکړم چې خپل شکايت پرېږدم، نو زۀ به خپل خفګان په خوشحالۍ بدل کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12091, 'Job 9:28', 'Job', 9, 28, '&nbsp;زۀ د خپلو ټولو تکليفونو نه يرېږم، ځکه چې زۀ په دې پوهيږم چې تاسو به ما بې ګناه ونۀ ګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12092, 'Job 9:29', 'Job', 9, 29, '&nbsp;چې زۀ مجرم ګڼلے شم، نو زۀ بيا بې‌فائدې خوارى ولې کوم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12093, 'Job 9:30', 'Job', 9, 30, '&nbsp;کۀ زۀ خپل ځان په واوره ووينځم او خپل لاسونه په صابون پاک کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12094, 'Job 9:31', 'Job', 9, 31, '&nbsp;خو تۀ به ما يوې ګنده کندې ته وروغورزوې، او زما خپلې جامې به زما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12095, 'Job 9:32', 'Job', 9, 32, '&nbsp;هغه زما په شان فانى انسان نۀ دے، نو ځکه نۀ ورسره بحث کولے شم او نۀ يې د جرګې ځائ ته بوتلے شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12096, 'Job 9:33', 'Job', 9, 33, '&nbsp;زمونږ په مينځ کښې روغه کوونکے نشته، چې هغه زمونږ دواړو روغه جوړه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12097, 'Job 9:34', 'Job', 9, 34, '&nbsp;کۀ مينځګړے ما د خُدائ پاک د سزا نه بچ کړى نو زۀ به بيا په يره کښې ژوند نۀ تېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12098, 'Job 9:35', 'Job', 9, 35, '&nbsp;بيا به زۀ ډاډه خبرې کوم چې د هغۀ يره زما په زړۀ کښې نۀ وى خو چې ترڅو پورې دا يره وى نو زۀ نۀ شم کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12099, 'Job 10:1', 'Job', 10, 1, '&nbsp;زۀ د خپل ژوند نه نفرت کوم، زۀ به ډېر شکايتونه کوم، زۀ به په مايوسۍ کښې خبرې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12100, 'Job 10:2', 'Job', 10, 2, '&nbsp;زۀ به خُدائ پاک ته ووايم چې ما مۀ رد کوه، او تۀ چې په ما کوم اِلزام لګوې نو د هغې نه ما خبر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');